const ROUTES={
 vinatigos:{title:'El bosque de los viñátigos',desc:'Una caminata circular por Agua García entre viñátigos centenarios y monteverde.',kind:'Circular',color:'#ec6b3f',track:TRACKS.vinatigos},
 orotava:{title:'La Orotava secreta · Ruta Azul',desc:'Paseo urbano guiado por la historia, las casas señoriales y las tradiciones de La Orotava.',kind:'Paseo urbano',color:'#156ee8',track:TRACKS.orotava},
 fortaleza:{title:'Chanajiga → La Fortaleza · Día 2',desc:'Ruta circular de alta exigencia entre el monteverde, los pinares y el paisaje volcánico de La Fortaleza. Recorrido real aportado en GPX.',kind:'Circular · montaña',color:'#bf582d',track:TRACKS.fortaleza}
};
const nav=document.querySelector('.nav'),menu=document.querySelector('.menu');
if(nav&&menu){menu.addEventListener('click',()=>{let open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));}
let map=null,layer=null;
if(window.L){map=L.map('map',{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);map.setView([28.43,-16.46],10)}
else {document.querySelector('.map-wrap #map').textContent='Se requiere conexión a Internet para cargar el mapa.'}
function updateRoute(key){
 const r=ROUTES[key]; if(!r)return;
 document.querySelectorAll('[data-route]').forEach(b=>{const active=b.dataset.route===key;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});
 document.querySelector('#map-title').textContent=r.title;
 document.querySelector('#map-desc').textContent=r.desc;
 document.querySelector('#map-kind').textContent=r.kind;
 const btn=document.querySelector('#map-download'), badge=document.querySelector('.map-badge'),distance=document.querySelector('#map-length');
 const mapEl=document.querySelector('#map'), embed=document.querySelector('#fortaleza-embed');
 embed.hidden=true;mapEl.hidden=false;
 btn.href='#';btn.removeAttribute('target');btn.removeAttribute('rel');btn.setAttribute('download',key+'.gpx');btn.textContent='Descargar archivo GPX ↓';
 badge.textContent=key==='fortaleza'?'DÍA 2 · RECORRIDO REAL GPX':'RECORRIDO REAL · GPX APORTADO';
 const track=r.track; distance.textContent=track.features[0].properties.distance_km_approx+' km aprox.';
 // Se genera una descarga GPX de las coordenadas GeoJSON, sin solicitudes de archivos externos.
 const points=track.features[0].geometry.coordinates;
 const gpx='<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Proyecto Tenerife 2027" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>'+r.title+'</name><trkseg>'+points.map(p=>'<trkpt lat="'+p[1]+'" lon="'+p[0]+'">'+(p.length>2?'<ele>'+p[2]+'</ele>':'')+'</trkpt>').join('')+'</trkseg></trk></gpx>';
 if(btn.dataset.objectUrl)URL.revokeObjectURL(btn.dataset.objectUrl);
 const url=URL.createObjectURL(new Blob([gpx],{type:'application/gpx+xml'}));btn.dataset.objectUrl=url;btn.href=url;
 if(map){if(layer)map.removeLayer(layer);layer=L.geoJSON(track,{style:{color:r.color,weight:6,opacity:1}}).addTo(map);map.invalidateSize();map.fitBounds(layer.getBounds(),{padding:[32,32],maxZoom:15});setTimeout(()=>map.invalidateSize(),150)}
}
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>updateRoute(b.dataset.route)));
updateRoute('vinatigos');
